#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
# Copyright (c) 2024-2026 Friehub
#
# Public API snapshots: one committed text file per publishable crate under
# `api/`, listing every public item (`cargo public-api`). Agents read these
# instead of crawling the source to learn what already exists.
#
#   .github/scripts/public-api.sh          regenerate api/*.txt
#   .github/scripts/public-api.sh --check  fail if api/*.txt are stale (CI)
#
# Needs `cargo install cargo-public-api --version 0.52.0 --locked` and the
# Rust toolchain named in API_RUSTC (rustdoc JSON is only stable per version).
# No nightly toolchain is required: RUSTC_BOOTSTRAP=1 lets stable emit the
# JSON, which is then passed to cargo-public-api with --rustdoc-json.
set -euo pipefail

API_RUSTC="1.97.0"
CRATES=(frensense frensense-engine frensense-lang frensense-bundler)
MODE="${1:-generate}"

cd "$(dirname "${BASH_SOURCE[0]}")/../.."

if ! command -v cargo-public-api >/dev/null; then
  echo "cargo-public-api not found: cargo install cargo-public-api --version 0.52.0 --locked" >&2
  exit 2
fi
have="$(rustc --version | awk '{print $2}')"
if [[ "$have" != "$API_RUSTC" ]]; then
  echo "note: snapshots are produced with rustc $API_RUSTC, you have $have;" >&2
  echo "      run 'rustup run $API_RUSTC ...' or accept possible format drift." >&2
fi

out_dir="api"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
target="${CARGO_TARGET_DIR:-target}/public-api"

for crate in "${CRATES[@]}"; do
  RUSTC_BOOTSTRAP=1 CARGO_TARGET_DIR="$target" \
    RUSTDOCFLAGS="-Z unstable-options --output-format json" \
    cargo doc -p "$crate" --lib --no-deps --all-features --quiet
  json="$target/doc/${crate//-/_}.json"
  {
    echo "# Public API of $crate. Generated by .github/scripts/public-api.sh; do not edit."
    cargo public-api --rustdoc-json "$json" -sss
  } >"$tmp/$crate.txt"
done

if [[ "$MODE" == "--check" ]]; then
  status=0
  for crate in "${CRATES[@]}"; do
    if ! diff -u "$out_dir/$crate.txt" "$tmp/$crate.txt" >"$tmp/$crate.diff"; then
      echo "api/$crate.txt is stale. Public items changed:" >&2
      grep -E '^[+-]pub ' "$tmp/$crate.diff" | head -60 >&2 || true
      status=1
    fi
  done
  [[ $status -eq 0 ]] || { echo "Run .github/scripts/public-api.sh and commit api/." >&2; exit 1; }
  echo "public API snapshots are current"
else
  mkdir -p "$out_dir"
  for crate in "${CRATES[@]}"; do cp "$tmp/$crate.txt" "$out_dir/$crate.txt"; done
  wc -l "$out_dir"/*.txt
fi
